60	async function probeSections(page: Page): Promise<Record<string, Probe>> {
61	  return await page.evaluate(
62	    ({ sections, props }) => {
63	      const out: Record<string, Probe> = {};
64	      for (const s of sections) {
65	        const el = document.querySelector(s.selector) as HTMLElement | null;
66	        if (!el) {
67	          out[s.id] = { found: false, bbox: null, computed: null, childCount: 0 };
68	          continue;
69	        }
70	        const r = el.getBoundingClientRect();
71	        const cs = window.getComputedStyle(el);
72	        const computed: Record<string, string> = {};
73	        for (const p of props) computed[p] = cs.getPropertyValue(p) || (cs as unknown as Record<string, string>)[p] || "";
74	        out[s.id] = {
75	          found: true,
76	          bbox: { x: r.x, y: r.y, width: r.width, height: r.height },
77	          computed,
78	          childCount: el.children.length,
79	        };
80	      }
81	      return out;
82	    },
83	    { sections: SECTIONS, props: PROBE_PROPS as unknown as string[] },
84	  );
85	}
