130	function diffComputed(live: Probe, local: Probe) {
131	  const out: Record<string, { live: string; local: string }> = {};
132	  if (!live.found || !local.found) return out;
133	  if (!live.computed || !local.computed) return out;
134	  for (const k of Object.keys(live.computed)) {
135	    const a = live.computed[k];
136	    const b = local.computed[k];
137	    if (a !== b) out[k] = { live: a, local: b };
138	  }
139	  return out;
140	}
